import { API_URL } from '../../../config.js';
import type { DrillPorts } from './tone-drill-session.js';
import { createComponentLogger } from '../../../utils/component-logger.js';

const log = createComponentLogger('tone-drill');

/**
 * Story 442: the drill's ports on the real Web APIs — `Audio` for clips, `SpeechRecognition` (vi-VN) for
 * answers, `speechSynthesis` for feedback. Each one stops what it is doing when the session's signal aborts.
 */

const LANG = 'vi-VN';
const ON_DEVICE: SpeechRecognitionOptions = { langs: [LANG], processLocally: true };
/** How many of Chrome's guesses the answer matcher sees. */
const MAX_ALTERNATIVES = 5;

export type RecognitionMode = 'on-device' | 'cloud';

/**
 * On the phone when Chrome has vi-VN there, installing it first when it can be downloaded; otherwise
 * Google's servers (DLR #137 found no Android packs). Call it from the start tap: `install` wants a gesture.
 */
export async function prepareRecognition(): Promise<RecognitionMode> {
    const availability = await SpeechRecognition.available(ON_DEVICE);
    log.info('on-device availability', { lang: LANG, availability });
    if (availability === 'available') return 'on-device';
    if (availability === 'downloadable' || availability === 'downloading') {
        const installed = await SpeechRecognition.install(ON_DEVICE);
        log.info('on-device install', { lang: LANG, installed });
        return installed ? 'on-device' : 'cloud';
    }
    return 'cloud';
}

/** Rejects with the signal's reason once it aborts, then silences the API — rejecting first, so an end event the stop fires cannot resolve it. */
function onAbort(signal: AbortSignal, reject: (reason: unknown) => void, stop: () => void): void {
    signal.addEventListener('abort', () => {
        reject(signal.reason);
        stop();
    }, { once: true });
}

export function browserDrillPorts(mode: RecognitionMode): DrillPorts {
    return {
        play(audio, signal) {
            return new Promise((resolve, reject) => {
                const element = new Audio(`${API_URL}/api/media/audio/${audio}`);
                element.onended = () => resolve();
                element.onerror = () => {
                    const error = new Error(`Audio ${audio}: ${element.error?.message ?? 'unknown media error'} (code ${element.error?.code})`);
                    log.error('clip failed', { audio, error: error.message });
                    reject(error);
                };
                onAbort(signal, reject, () => element.pause());
                element.play().catch((err: unknown) => {
                    log.error('clip play() refused', { audio, error: err instanceof Error ? `${err.name}: ${err.message}` : String(err) });
                    reject(err);
                });
            });
        },

        listen(signal) {
            return new Promise((resolve, reject) => {
                const recognition = new SpeechRecognition();
                recognition.lang = LANG;
                recognition.continuous = false;
                recognition.interimResults = false;
                recognition.maxAlternatives = MAX_ALTERNATIVES;
                recognition.processLocally = mode === 'on-device';

                let heard: string[] | null = null;
                let failed = false;
                recognition.onresult = (event) => {
                    heard = Array.from(event.results[0], (alternative) => alternative.transcript);
                };
                recognition.onerror = (event) => {
                    if (event.error === 'no-speech' || event.error === 'aborted') return;
                    log.error('recognition error', { mode, error: event.error, message: event.message });
                    failed = true;
                    reject(new Error(`SpeechRecognition ${event.error}: ${event.message}`));
                };
                recognition.onend = () => {
                    if (!failed) resolve(heard);
                };
                onAbort(signal, reject, () => recognition.abort());
                recognition.start();
            });
        },

        say(text, signal) {
            return new Promise((resolve, reject) => {
                const utterance = new SpeechSynthesisUtterance(text);
                utterance.lang = LANG;
                utterance.onend = () => resolve();
                utterance.onerror = (event) => {
                    if (signal.aborted) return; // cancel() from the stop tap, already rejected
                    log.error('speech failed', { text, error: event.error });
                    reject(new Error(`speechSynthesis ${event.error}`));
                };
                onAbort(signal, reject, () => speechSynthesis.cancel());
                speechSynthesis.speak(utterance);
            });
        },

        random: () => Math.random(),
    };
}
